    const next = new Uint8Array(T);
    for (let t = 0; t + 1 < T - k; t++) next[t] = cur[t + 1] ^ (cur[t] | prev[t]);
    row[k] = next[t0];
    prev = cur; cur = next;
  }
  return row;
}

function leastEventualPeriod(col, T, QMAX, lo) {
  for (let q = 1; q <= QMAX; q++) {
    let ok = true;
    for (let t = lo; t + q < T; t++) if (col[t + q] !== col[t]) { ok = false; break; }
